%spark

// ============================================
// OPTIONAL EXTENSION: HBASE IMPLEMENTATION
// Simplified version - No hanging commands
// ============================================

println("="*70)
println("OPTIONAL EXTENSION: HBASE IMPLEMENTATION")
println("="*70)

// ============================================
// STEP 1: Export DataFrames to CSV for HBase
// ============================================
println("\n[STEP 1] Exporting DataFrames to CSV format...")

val hbaseTempDir = "/tmp/hbase_import"
import java.io.File
def deleteDir(dir: File): Unit = {
  if (dir.exists()) {
    dir.listFiles().foreach { f =>
      if (f.isDirectory) deleteDir(f) else f.delete()
    }
    dir.delete()
  }
}
deleteDir(new File(hbaseTempDir))
new File(hbaseTempDir).mkdirs()

// Export top 10 movies
top10MoviesDF.select(
  col("title").as("movie_title"),
  col("avg_rating"),
  col("rating_count")
).coalesce(1).write.mode("overwrite").option("header", "true").csv(s"$hbaseTempDir/top_movies")
println("  ✓ Exported top_movies")

// Export user favorite genre
userFavoriteGenreDF.coalesce(1).write.mode("overwrite").option("header", "true").csv(s"$hbaseTempDir/user_genres")
println("  ✓ Exported user_genres")

// Export young users
youngUsersDF.coalesce(1).write.mode("overwrite").option("header", "true").csv(s"$hbaseTempDir/young_users")
println("  ✓ Exported young_users")

// Export scientists
scientistUsersDF.coalesce(1).write.mode("overwrite").option("header", "true").csv(s"$hbaseTempDir/scientists")
println("  ✓ Exported scientists")

println(s"✓ All data exported to $hbaseTempDir")

// ============================================
// STEP 2: Read data back using Spark (CSV)
// ============================================
println("\n[STEP 2] Reading data from CSV files...")

val sparkTopMovies = spark.read.option("header", "true").csv(s"$hbaseTempDir/top_movies")
val sparkUserGenres = spark.read.option("header", "true").csv(s"$hbaseTempDir/user_genres")
val sparkYoungUsers = spark.read.option("header", "true").csv(s"$hbaseTempDir/young_users")
val sparkScientists = spark.read.option("header", "true").csv(s"$hbaseTempDir/scientists")

println("\n--- Data from CSV files (representing HBase data) ---")
println("Top Movies:")
sparkTopMovies.show(10, false)

println("\nUser Genres (first 10):")
sparkUserGenres.show(10, false)

println("\nYoung Users (first 10):")
sparkYoungUsers.show(10, false)

println("\nScientists:")
sparkScientists.show(15, false)

// ============================================
// STEP 3: HBase Code Template (for documentation)
// ============================================
println("\n" + "="*70)
println("HBASE IMPLEMENTATION CODE TEMPLATE")
println("="*70)

println("""
The following code demonstrates how to write to HBase when available:

```scala
// 1. Configure HBase connection
import org.apache.hadoop.hbase.HBaseConfiguration
import org.apache.hadoop.hbase.client._
import org.apache.hadoop.hbase.util.Bytes

val hbaseConf = HBaseConfiguration.create()
hbaseConf.set("hbase.zookeeper.quorum", "localhost")
hbaseConf.set("hbase.zookeeper.property.clientPort", "2181")

// 2. Create HBase tables (run once)
// hbase shell commands:
//   create 'movielens_top_movies', 'cf'
//   create 'movielens_user_genres', 'cf'
//   create 'movielens_young_users', 'cf'
//   create 'movielens_scientists', 'cf'

// 3. Write to HBase using DataFrame API
top10MoviesDF.write
  .format("org.apache.hadoop.hbase.spark")
  .option("hbase.columns.mapping", "cf:title title, cf:avg_rating avg_rating, cf:rating_count rating_count")
  .option("hbase.table", "movielens_top_movies")
  .mode("overwrite")
  .save()

// 4. Read from HBase
val hbaseDF = spark.read
  .format("org.apache.hadoop.hbase.spark")
  .option("hbase.table", "movielens_top_movies")
  .load()
hbaseDF.show(10, false)
